// 100 MORE SWATCH CANDIDATES (2026-08-01, owner asked for another hundred) —
// same contract as themes-catalogue.mjs: object-form, rendered via
// themeCss(object), NOTHING ships until picked, `needs` records what the
// engine cannot do yet. Ten families of ten, each theme named after a
// CONCRETE referent — a material, a room, a trade, an era — because that is
// where distinctive choices come from; a theme named after an adjective ends
// up cream with a serif and terracotta.
//
// House discipline throughout: every radius decisive (≤0.375rem or
// ≥0.875rem), components declared where the genre has them (buttons/inputs/
// offset), papers NOT all white (chambray, kraft, butcher pink, greenbar,
// platinum, shell), accents spread across the wheel, Inter as body text three
// times in a hundred. `shot: "dark"` marks the themes whose identity IS dark
// mode — the swatch renders that mode.
const T = (o) => ({ radius: "0.25rem", corner: "round", scale: "standard", tracking: "neutral",
  leading: "standard", weight: "standard", density: "standard", border: "hairline",
  shadow: "crisp", icon: "regular", ...o });

